public sealed class Attempt
{
    public Attempt(string id, string tenantId)
    {
        if (string.IsNullOrWhiteSpace(id)) throw new ArgumentException("id");
        Id = id;
        TenantId = tenantId;
    }

    public string Id { get; }
    public string TenantId { get; }
    public int Score { get; private set; }
    public void ApplyScore(int score) => Score = score >= 0 ? score : throw new ArgumentOutOfRangeException(nameof(score));
}

public sealed record AttemptCacheDto(string Id, string TenantId, int Score);

public static Attempt ToDomain(this AttemptCacheDto dto)
{
    var attempt = new Attempt(dto.Id, dto.TenantId);
    attempt.ApplyScore(dto.Score);
    return attempt;
}

static bool TryMapRow(ReadOnlySpan<char> line, out AttemptCacheDto dto)
{
    dto = default!;
    if (!TryReadScore(line, out var id, out var score)) return false;
    dto = new AttemptCacheDto(id.ToString(), tenantId: "import", score);
    return true;
}
